// Keloid: plan view (top) and longitudinal section along the incision (bottom), same x scale.
const CX = 320, PY = 232, SKY = 440, I0 = 230, I1 = 410;   // incision runs x 230..410
const RED = "#c0392b", INK = "#16323a";
let el = {};
function txt(api, parent, s, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-weight": 700, "font-size": 18}, attrs), parent);
  t.textContent = s; return t;
}
function chip(api, parent, s, cx, cy, w, color, stroke) {
  const g = api.el("g", {}, parent);
  api.el("rect", {x: cx - w / 2, y: cy - 16, width: w, height: 32, rx: 16, fill: "#ffffff", stroke: stroke, "stroke-width": 2, filter: "url(#chipShadow)"}, g);
  txt(api, g, s, {x: cx, y: cy + 1, "text-anchor": "middle", "dominant-baseline": "central", fill: color});
  return g;
}
// Keloid outline in plan: a rounded strip (half-length L, half-width W) whose rim becomes
// irregular, with claw-like lobes, as it invades (claw 0..1). Computed, not morphed art.
function plan(L, W, claw) {
  let d = "";
  for (let i = 0; i <= 160; i++) {
    const a = 2 * Math.PI * i / 160, c = Math.cos(a), s = Math.sin(a);
    const bump = 1 + claw * (0.16 * Math.sin(5 * a + 0.6) + 0.09 * Math.sin(11 * a + 2.1) + 0.12 * Math.pow(Math.abs(c), 6) * Math.sin(3 * a + 1));
    const x = CX + L * Math.sign(c) * Math.pow(Math.abs(c), 0.45) * (1 + 0.04 * claw * Math.sin(7 * a));
    const y = PY + W * bump * Math.sign(s) * Math.pow(Math.abs(s), 0.8);
    d += (i ? " L " : "M ") + x.toFixed(1) + " " + y.toFixed(1);
  }
  return d + " Z";
}
// Section: a firm mound raised above the skin level and extending down into the dermis.
function side(L, H, Hd) {
  let up = "", dn = "";
  for (let i = 0; i <= 80; i++) {
    const u = -1 + 2 * i / 80, x = CX + L * u, k = Math.pow(Math.max(0, 1 - u * u), 0.55);
    const lump = 1 + 0.06 * Math.sin(9 * u + 1);
    up += (i ? " L " : "M ") + x.toFixed(1) + " " + (SKY - H * k * lump).toFixed(1);
    dn = " L " + x.toFixed(1) + " " + (SKY + Hd * Math.pow(Math.max(0, 1 - u * u), 0.8)).toFixed(1) + dn;
  }
  return up + dn + " Z";
}
function setup(api) {
  const pl = api.$("#plan"), sd = api.$("#side"), top = api.$("#top"), pores = api.$("#pores");
  const r = api.random(5);
  for (let i = 0; i < 70; i++) api.el("circle", {cx: 56 + r() * 528, cy: 148 + r() * 166, r: 1.2 + r() * 1.2}, pores);
  // healed incision line
  api.el("path", {d: "M " + I0 + " " + PY + " L " + I1 + " " + PY, stroke: "#9b5a4c", "stroke-width": 3, "stroke-linecap": "round"}, pl);
  el.kTop = api.el("path", {fill: "url(#kel)", stroke: "#9d2f39", "stroke-width": 2, filter: "url(#kit-volume)"}, pl);
  el.gloss = api.el("ellipse", {fill: "#ffffff", opacity: 0.16, filter: "url(#kit-glow)"}, pl);
  // original incision outline stays visible on top
  el.outline = api.el("rect", {x: I0 - 10, y: PY - 12, width: I1 - I0 + 20, height: 24, rx: 12, fill: "none", stroke: "#ffffff", "stroke-width": 2.6, "stroke-dasharray": "7 6"}, pl);
  el.leader = api.el("line", {x1: 230, y1: 182, x2: 262, y2: PY - 13, stroke: INK, "stroke-width": 2}, top);
  el.cInc = chip(api, top, "Original incision", 180, 168, 170, INK, "@line");
  // section
  el.kSide = api.el("path", {fill: "url(#kelSide)", stroke: "#9d2f39", "stroke-width": 2, filter: "url(#kit-volume)"}, sd);
  api.el("line", {x1: 48, y1: SKY, x2: 592, y2: SKY, stroke: INK, "stroke-width": 2, "stroke-dasharray": "8 7", opacity: 0.75}, sd);
  [I0, I1].forEach(x => api.el("line", {x1: x, y1: 372, x2: x, y2: 484, stroke: INK, "stroke-width": 2, "stroke-dasharray": "4 5", opacity: 0.6}, sd));
  txt(api, sd, "skin level", {x: 576, y: 427, "text-anchor": "end", fill: "@muted", stroke: "#ffffff", "stroke-width": 5, "paint-order": "stroke", "stroke-linejoin": "round"});
  txt(api, top, "Top view", {x: 62, y: 304, fill: "#ffffff", "font-size": 16, opacity: 0.95});
  txt(api, top, "Side view", {x: 62, y: 372, fill: "@muted", "font-size": 16});
  // beyond-the-incision arrows (both views)
  el.arrows = api.el("g", {stroke: RED, "stroke-width": 4, "stroke-linecap": "round", "stroke-linejoin": "round", fill: "none"}, top);
  el.arrowL = api.el("path", {d: "M 222 380 L 156 380 M 166 371 L 156 380 L 166 389"}, el.arrows);
  el.arrowR = api.el("path", {d: "M 418 380 L 484 380 M 474 371 L 484 380 L 474 389"}, el.arrows);
  el.cKel = chip(api, top, "Keloid", 320, 294, 104, RED, "#f0b7ae");
}
function vis(api, node, k) { api.set(node, {opacity: k, display: k > 0.001 ? "inline" : "none"}); }
function render(t, api) {
  const rise = api.seg(t, 150, 2000, "ease_in_out");          // beat 1: raised along the line
  const spread = api.seg(t, 2400, 4400, "ease_in_out");       // beat 2: invades past the margins
  const L = 92 + 70 * spread, W = 4 + 10 * rise + 20 * spread;
  api.set(el.kTop, {d: plan(L, W, spread)});
  api.set(el.gloss, {cx: CX - 0.25 * L, cy: PY - 0.35 * W, rx: 0.3 * L, ry: Math.max(1, 0.18 * W)});
  api.set(el.kSide, {d: side(L, 4 + 26 * rise + 14 * spread, 6 + 8 * rise + 12 * spread)});
  // beat 3: outline and arrows mark what lies beyond the incision
  const b3 = api.seg(t, 4650, 5100, "ease_out");
  api.set(el.outline, {stroke: b3 > 0 ? "#ffd166" : "#ffffff", "stroke-width": 2.6 + 1.2 * b3});
  vis(api, el.arrows, b3);
  api.set(el.arrows, {transform: "translate(0 0)"});
  api.set(el.arrowL, {transform: "translate(" + (14 * (1 - b3)).toFixed(1) + " 0)"});
  api.set(el.arrowR, {transform: "translate(" + (-14 * (1 - b3)).toFixed(1) + " 0)"});
  const kc = api.seg(t, 5000, 5400, "back_out");
  vis(api, el.cKel, api.seg(t, 5000, 5200));
  api.set(el.cKel, {transform: "translate(320 294) scale(" + (0.8 + 0.2 * kc).toFixed(3) + ") translate(-320 -294)"});
}
